package app.onklav.home

import android.content.Context
import androidx.test.core.app.ApplicationProvider
import androidx.media3.transformer.Composition
import kotlinx.coroutines.runBlocking
import okhttp3.*
import okhttp3.ResponseBody.Companion.toResponseBody
import okhttp3.MediaType.Companion.toMediaType
import org.json.*
import org.junit.Assert.*
import org.junit.Test
import org.junit.runner.RunWith
import org.robolectric.RobolectricTestRunner
import org.robolectric.annotation.Config
import java.io.File

@RunWith(RobolectricTestRunner::class) @Config(sdk=[29])
class YoutubeMediaRepairsTest{
 private fun url(itag:Int=137,id:String="main")="https://r1.googlevideo.com/videoplayback?source=youtube&itag=$itag&id=$id&range=0-3"
 private fun format(itag:Int,mime:String,h:Int,audio:Boolean,raw:String="",identity:String="main")=JSONObject().put("itag",itag).put("mime",mime).put("height",h).put("audio",audio).put("url",raw).put("identity",identity)
 @Test fun downloadArrowReplacesOnlyHomeAndLeavesOriginalFrameUntouched(){val f=JSONObject().put("actions",JSONArray(listOf(JSONObject().put("id","home").put("icon","home").put("long_action","viewer.reset"),JSONObject().put("id","history"),JSONObject().put("id","channels"),JSONObject().put("id","bookmarks"))));val changed=youtubeDownloadHeader(f).getJSONArray("actions");assertEquals("download",changed.getJSONObject(0).getString("id"));assertEquals("download",changed.getJSONObject(0).getString("icon"));assertFalse(changed.getJSONObject(0).has("long_action"));assertEquals(listOf("download","history","channels","bookmarks"),(0 until changed.length()).map{changed.getJSONObject(it).getString("id")});assertEquals("home",f.getJSONArray("actions").getJSONObject(0).getString("id"))}
 @Test fun currentVideoStreamsRejectAdsStalePagesAndUnsupportedQuality(){val s=YoutubeStreams();s.bind("AbC_def-123");s.manifest(JSONObject().put("video",s.video).put("ad",false).put("streams",JSONArray(listOf(format(137,"video/mp4",1080,false),format(140,"audio/mp4",0,true,url(140))))));s.observe(url(id="advertisement"));assertThrows(IllegalStateException::class.java){s.select(false,1080)};s.observe(url());val v=s.select(false,1080);assertEquals(1080,v.first.height);assertEquals(140,v.second!!.itag);assertFalse(v.first.url.contains("range="));assertEquals(140,s.select(true,480).first.itag);assertEquals(1080,s.select(false,480).first.height);s.bind("OtherId-123");assertTrue(s.candidates().isEmpty());s.manifest(JSONObject().put("video","AbC_def-123").put("ad",false).put("streams",JSONArray(listOf(format(137,"video/mp4",1080,true,url())))));assertTrue(s.candidates().isEmpty());assertThrows(IllegalArgumentException::class.java){YoutubeStreams.complete("https://private.example/videoplayback")};assertThrows(IllegalArgumentException::class.java){YoutubeStreams.complete(url()+"&sparams=range")}}
 @Test fun changedEditsUseCompositionAndUneditedClipUsesStandardDecoder(){val c=VideoClip(file="${videoId()}.media",name="Phone clip",sourceMs=8300);val p=VideoProject(clips=listOf(c));assertTrue(VideoComposition.directPreview(p));assertFalse(VideoComposition.directPreview(p.copy(clips=listOf(c.copy(brightness=.1f)))));assertFalse(VideoComposition.directPreview(p.copy(clips=listOf(c.copy(titles=listOf(VideoTitle()))))));assertFalse(VideoComposition.directPreview(p.copy(clips=listOf(c,c.copy(id=videoId())))));assertFalse(VideoComposition.directPreview(p.copy(fill=true)));val folder=File(ApplicationProvider.getApplicationContext<Context>().filesDir,"video-test");val compatible=VideoComposition.build(p,folder,true,true);assertEquals(Composition.HDR_MODE_TONE_MAP_HDR_TO_SDR_USING_MEDIACODEC,compatible.hdrMode);assertTrue(compatible.effects.videoEffects.isEmpty());assertEquals(Composition.HDR_MODE_TONE_MAP_HDR_TO_SDR_USING_MEDIACODEC,VideoComposition.build(p,folder).hdrMode)}
 @Test fun segmentedMediaDownloadTracksActualBytesAndFollowsCheckedRedirect(){val target=File(ApplicationProvider.getApplicationContext<Context>().cacheDir,"youtube-range-test");val payload="complete-media-file".toByteArray();var requests=0;var last=0L;val client=OkHttpClient.Builder().addInterceptor{chain->val request=chain.request();requests++;if(request.url.queryParameter("redirect")=="yes")Response.Builder().request(request).protocol(Protocol.HTTP_1_1).code(302).message("Redirect").header("Location",url().replace("&range=0-3","")).body(ByteArray(0).toResponseBody()).build()else{val start=request.header("Range")!!.substringAfter("bytes=").substringBefore('-').toInt();val end=minOf(start+3,payload.lastIndex);Response.Builder().request(request).protocol(Protocol.HTTP_1_1).code(206).message("Partial").header("Content-Range","bytes $start-$end/${payload.size}").header("ETag","\"stable\"").body(payload.copyOfRange(start,end+1).toResponseBody("video/mp4".toMediaType())).build()}}.build();runBlocking{YoutubeDownload.transfer(url()+"&redirect=yes",target,"Test",{},sourceClient=client,progress={done,total->assertTrue(done>last);last=done;assertEquals(payload.size.toLong(),total)})};assertArrayEquals(payload,target.readBytes());assertEquals(payload.size.toLong(),last);assertEquals(1+(payload.size+3)/4,requests);target.delete()}
 @Test fun portraitAndLandscapeDownloadsKeepRequestedShortEdgeAndNeverUpscale(){assertEquals(1920 to 1080,youtubeDimensions(3840,2160,1080));assertEquals(1080 to 1920,youtubeDimensions(1080,1920,1080));assertEquals(480 to 854,youtubeDimensions(1080,1920,480));assertThrows(IllegalArgumentException::class.java){youtubeDimensions(640,360,480)}}
 @Test fun brokenRangeResponseCannotBePublishedAsComplete(){val target=File(ApplicationProvider.getApplicationContext<Context>().cacheDir,"youtube-broken-test");val client=OkHttpClient.Builder().addInterceptor{chain->Response.Builder().request(chain.request()).protocol(Protocol.HTTP_1_1).code(206).message("Partial").header("Content-Range","bytes 5-9/10").body("short".toResponseBody("video/mp4".toMediaType())).build()}.build();assertThrows(IllegalArgumentException::class.java){runBlocking{YoutubeDownload.transfer(url(),target,"Test",{},client,{_,_->})}};assertEquals(0,target.length());target.delete()}
}
